result = json.loads(data['result'])
experiments = result['data']['experiments']

# Get full metrics for exp_008d_subsample_on_h8
exp = experiments.get('exp_008d_subsample_on_h8', {})
m = exp.get('metrics', {}) or {}
ve_keys = [k for k in m.keys() if 'value_eval_ratio' in k]
print('exp_008d_subsample_on_h8 ve_ratio keys:')
for k in sorted(ve_keys):
    print(f'  {k} = {m[k]}')

# Get ve_ratio for baseline seeds
print()
for sid in ['exp_001_baseline_s2', 'exp_001_baseline_s3', 'exp_001_baseline_s4',
            'exp_001_baseline_s2_extended', 'exp_001_baseline_s3_extended', 'exp_001_baseline_s4_extended']:
    if sid in experiments:
        exp = experiments[sid]
        m = exp.get('metrics', {}) or {}
        ve_keys = [k for k in m.keys() if 've_ratio' in k.lower()]
        print(f'{sid}: {[(k, m[k]) for k in ve_keys]}')

# Get exp_008c details
print()
for sid in ['exp_008c', 'exp_008c_no_subsample_dt2_h8']:
    if sid in experiments:
        exp = experiments[sid]
        m = exp.get('metrics', {}) or {}
        ve_keys = [k for k in m.keys() if 'value_eval_ratio' in k or 'nve' in k.lower()]
        print(f'{sid}: {[(k, m[k]) for k in sorted(ve_keys)]}')

# Get exp_008f details (all variants)
print()
for eid in sorted(experiments.keys()):
    if eid.startswith('exp_008f'):
        exp = experiments[eid]
        m = exp.get('metrics', {}) or {}
        nve_keys = [k for k in m.keys() if 'nve' in k.lower() or 'peak_nve' in k.lower()]
        ve_keys = [k for k in m.keys() if 'value_eval_ratio' in k]
        all_keys = nve_keys + ve_keys
        if all_keys:
            print(f'{eid}: {[(k, m[k]) for k in sorted(all_keys)]}')
